package lifequest.quests;
import lifequest.Main;import lifequest.database.*;import lifequest.database.QuestDAO.Quest;import lifequest.model.User;import lifequest.ui.Style;import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.util.*;
public class QuestPanel extends JPanel {
 private final Main main;private final User user;private final DefaultTableModel model;private final JTable table;
 public QuestPanel(Main m,User u){main=m;user=u;setBackground(Style.BACKGROUND);setLayout(new BorderLayout(12,12));setBorder(BorderFactory.createEmptyBorder(25,25,25,25));JPanel top=new JPanel(new BorderLayout());top.setOpaque(false);top.add(Style.title("Quests"),BorderLayout.WEST);JButton create=Style.button("+ Create Quest");create.addActionListener(e->create());top.add(create,BorderLayout.EAST);model=new DefaultTableModel(new Object[]{"ID","Quest","Category","Priority","Difficulty","XP","Repeat"},0){public boolean isCellEditable(int r,int c){return false;}};table=new JTable(model);table.setRowHeight(32);JButton complete=Style.button("Complete Selected Quest");complete.addActionListener(e->complete());add(top,BorderLayout.NORTH);add(Style.scroll(table),BorderLayout.CENTER);add(complete,BorderLayout.SOUTH);refresh();}
 private void create(){CreateQuestDialog d=new CreateQuestDialog(main,user);d.setVisible(true);if(d.isSaved())refresh();}
 private void complete(){int r=table.getSelectedRow();if(r<0){JOptionPane.showMessageDialog(this,"Select a quest.");return;}int id=(int)model.getValueAt(r,0),xp=(int)model.getValueAt(r,5);if(new QuestDAO().completeQuest(id)){addXp(xp);JOptionPane.showMessageDialog(this,"Quest completed! +"+xp+" XP");refresh();}}
 private void addXp(int x){int old=user.getLevel(),total=user.getXp()+x;int level=total/100+1;user.setXp(total);user.setLevel(level);user.setCoins(user.getCoins()+x/10);if(level>old){user.setHealth(Math.min(100,user.getHealth()+5));user.setFocus(Math.min(100,user.getFocus()+5));user.setDiscipline(Math.min(100,user.getDiscipline()+5));user.setStrength(Math.min(100,user.getStrength()+5));JOptionPane.showMessageDialog(this,"Level Up! You reached Level "+level+"!");}new UserDAO().updateProgress(user);}
 private void refresh(){model.setRowCount(0);for(Quest q:new QuestDAO().getActive(user.getId()))model.addRow(new Object[]{q.id,q.name,q.category,q.priority,q.difficulty,q.xp,q.repeatType});}
}
